package com.alpharip.staffmod.IncidentPostMortemBoard; public final class IncidentPostMortemValidator { private IncidentPostMortemValidator(){} public static void validate(String t,String d,String p){required(t,"Title");required(d,"Description");required(p,"Reporter");if(t.trim().length()>100)throw new IllegalArgumentException("Title exceeds 100 characters");if(d.trim().length()>2000)throw new IllegalArgumentException("Description exceeds 2000 characters");if(p.trim().length()>32)throw new IllegalArgumentException("Reporter exceeds 32 characters");} private static void required(String s,String l){if(s==null||s.trim().isEmpty())throw new IllegalArgumentException(l+" is required");} }